INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS101', 'Computer Programming and Utilization', 'CSE', 'http://www.cse.iitb.ac.in/~cs101', 'Prof. Abir De', 'Prof. Vinay J. Ribeiro', 'Autumn, Spring', '6', 'N/A', 'Full Semester', 'Theory + Lab', 'This course provides an introduction to problem solving with computers using a modern language such as Java or C/C++. Topics covered will include :
* Utilization : Developer fundamentals such as editor, integrated programming environment, Unix shell, modules, libraries.
* Programming features : Machine representation, primitive types,arrays and records, objects, expressions, control statements, iteration,procedures, functions, and basic i/o.
* Applications : Sample problems in engineering, science, text processing, and numerical methods.', 'Textbook
* C++ Program Design: An introduction to Programming and Object-Oriented Design, 3rd Edition, by Cohoon and Davidson, Tata McGraw Hill. 2003.
Other references (Not required reading)
* Thinking in C++ 2nd Edition by Bruce Eckel(available online).
* G. Dromey, How to Solve It by Computer, Prentice-Hall, Inc., Upper Saddle River, NJ, 1982.
* Polya, G., How to Solve _It (2nd ed.), Doubleday and co. (1957).
* Let Us C. Yashwant Kanetkar. Allied Publishers, 1998.
* The Java Tutorial, Sun Microsystems. Addison-Wesley, 1999.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS105', 'Discrete Structures', 'CSE', 'N/A', 'Prof. Bharat Adsul', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'N/A', 'Propositions and predicates, proofs and proof techniques. Sets, relations and functions, cardinality, basic counting. Posets and lattices: Dilworth`s theorem, inversion and distributive lattices. Graph theory : paths, cycles, trees, connectivity. Group theory : Lagrange`s theorem, homomorphisms, applications.', '1. Kenneth Rosen, Discrete Mathematics and its applications, 5th edition, Tata-McGraw Hill, 2002.2. C.L. Liu, Elements of Discrete mathematics, McGraw-Hill, 1985.3. D. B. West, Introduction to Graph Theory, Prentice Hall of India, 1998.4. M. Artin, Algebra, Prentice-Hall India, 1991.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS213', 'Data Structures and Algorithms', 'CSE', 'https://www.cse.iitb.ac.in/~akg/courses/2025-ds/', 'Prof. Manoj Prabhakaran', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Introduction to data structures, abstract data types, analysis of algorithms. Creation and manipulation of data structures: arrays, lists, stacks, queues, trees, heaps, hash tables, balanced trees, tries, graphs. Algorithms for sorting and searching, order statistics, depth-first and breadth-first search, shortest paths and minimum spanning tree.', '1. T. Cormen, C. Leiserson, R. Rivest, C. Stein, Introduction to Algorithms, 2nd edition, Prentice-Hall India, 2001.
2. S. Sahni, Data Structures, Algorithms and Applications in C++,2nd edition, Universities Press,2005.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS215', 'Data Interpretation and Analysis', 'CSE', 'https://www.cse.iitb.ac.in/~ajitvr/CS215/', 'Prof. Ajit Rajwade', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Covers descriptive statistics; discrete and continuous probability; random variables and expectation; special distributions (Bernoulli, Binomial, Geometric, Hypergeometric, Gaussian, Chi-square, Uniform, Poisson, Exponential); hypothesis testing', 'Course textbook: Introduction to Probability and Statistics for Engineers and Scientists: Fourth Edition (many copies available in the library)', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS228', 'Logic For CS', 'CSE', 'https://www.cse.iitb.ac.in/~akg/courses/2022-logic/', 'Prof. S. Akshay', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Propositional logic; natural deduction; propositional logic as a formal language; semantics of propositional logic; normal forms; SAT solvers. Predicate logic as a formal language; proof theory of predicate logic; semantics of predicate logic; undecidability and expressiveness of predicate logic. Program correctness: Hoare triples; partial and total correctness; proof calculus; programming by contract. Other applications: logic in databases, logic programming, puzzle solving. Practice with verification tools.', 'Logic in Computer Science. Huth and Ryan.Cambridge University Press, 2004', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS230', 'Digital Logic Design and Computer Architecture', 'CSE', 'N/A', 'Prof. Sayandeep Saha', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'N/A', 'Logic gates, SOP, POS, KMAPs, Number system: fixed point, floating-point, combinational circuits; sequential circuits, FSMs, FSM Minimization; intro to processors, CPU, Von Neumann architecture, ISA vs microarchitecture, computer organization; instruction pipelining; superscalar processors, SMTs; memory hierarchy including virtual memory; caches, DRAM; storage and I/O; GPUs, TPUs, and accelerators; case study of recent processors and GPUs.', 'Patterson and Hennessy, Computer Organization and Design, MK Pub; Hennessy and Patterson, Computer Architecture, MK Pub; M. Mano, Digital Logic and Computer Design, Pearson; Harris and Harris, Digital Design and Computer Architecture, MK Pub.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS231', 'Digital Logic and Computer Architecture Lab', 'CSE', 'N/A', 'Prof. Biswabandan Panda', 'N/A', 'Autumn', '3', 'N/A', 'N/A', 'Lab', 'Labs on (a) Verilog/VHDL, (b) combinational and sequential circuits, (c) assembly language programming, (d) Instruction pipelining and superscalar processors, and (e) Memory hierarchy optimizations involving tools like Pin and architecture simulators,', 'N/A', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS293', 'Data Structures Lab', 'CSE', 'https://www.cse.iitb.ac.in/~akg/courses/2025-ds/', 'Prof. Manoj Prabhakaran', 'N/A', 'Autumn', '3', 'N/A', 'Full Semester', 'Lab', 'Implementation of, and experiments with, basic data structures and use in dynamic operations on data for different algorithms and problem domains; comparison of asymptotic complexity with real behaviour of algorithms; project.', 'Kathleen Jensen, Niklaus Wirth and A. Mickel, Pascal User Manual and Report: Iso Pascal Standard, Springer Verlag, 4th Edition, October 1991
Bruno R. Preiss, Data Structures and Algorithms with Object-Oriented Design Patterns in C++, Wiley & Sons (Asia), 2001
Sartaj Sahni, Data Structures, Algorithms, and Applications in C++, WCB McGraw-Hill, International Edition, 1998
Michael Goodrich and Roberto Tamassia, Data Structures and Algorithms in Java, Second Edition, Wiley & Sons (Asia), 2001', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS310', 'Automata Theory', 'CSE', 'N/A', 'Prof. Krishna S', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'N/A', 'Finite state machines (DFA/NFA/epsilon NFAs), regular expressions. Properties of regular languages. Myhill-Nerode Theorem. Non-regularity. Push down automata. Properties of context-free languages. Turing machines: Turing hypothesis, Turing computability, Nondeterministic, multi tape and other versions of Turing machines. Church`s thesis, recursively enumerable sets and Turing computability. Universal Turing machines. Unsolvability, The halting problem, partial solvability, Turing enumerability, acceptability and decidability, unsolvable problems about Turing Machines. Post`s correspondence problem.', '1.Introduction to Automata Theory, Languages and Computation, by John. E. Hopcroft, Rajeev Motwani, J. D. Ullman, published by Pearson Education Asia, 2006. 2.Elements of the Theory of Computation, by H.R.Lewis and C.H.Papadimitrou, published by Prentice Hall Inc, 1981.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS339', 'Abstractions and Paradigms for Programming', 'CSE', 'N/A', 'Prof. Manas Thakur', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Review of the program development process, Issues in program design, Structured programming, Data and control abstractions, Programming with assertions. Reasoning about programs and proving correctness of programs. Ideas behind imperative, applicative, object oriented and logic programming paradigms such as typing, expressions, pure functions, recursion, higher order functions, encapsulation, inheritance, goal satisfaction, backtracking, unification. Some of the ideas behind the implementation of the paradigms. Course to be centered around problems and applications that demonstrate the main themes.', '1. Harold Abelson, Gerald Jay Sussman and July Sussman, Structure and Interpretation of Computer Programs, 2nd edition, The MIT Press, 1996. 2. David A. Watt, Programming Language Concepts and Paradigms, Prentice-Hall, 1990. 3. Rajeev Sangal, Programming Paradigms in Lisp, McGraw Hill, 1991. 4. Ravi Sethi. Programming Languages: Concepts and Constructs, Second Edition, Pearson Education, 2006. 5. Michael L. Scott. Programming Language Pragmatics, Fourth Edition, Morgan Kaufmann. 6. William F. Clocksin, Christopher S. Mellish, Programming in Prolog, Springer, 2003.7. Programming Language Manuals which may be provided by the instructor.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS347M', 'Operating Systems', 'CSE', 'N/A', 'Prof. Varsha Apte', 'N/A', 'Autumn', '6', 'CS101 & CS213 M', 'N/A', 'N/A', 'Overview of operating systems: batch processing, multiprogramming, time-sharing and real time systems. Concurrent processes: communication and synchronisation. Process management, deadlocks. Main memory management: paging, segmentation, sharing of programs and data. Device management. Information management: file system, security. A case study of UNIX.', 'J.L.Galvin and A.Silberschatz, Operating System Concepts, Addison-Wesley, 1998. D.M.Dhamdhere, Systems Programming and Operating Systems, 1999. M.J.Bach, The design of UNIX operating system, Prentice Hall of India, 1986. Uresh Vahalia, UNIX Internals: The New Frontiers, Prentice Hall, 1996. A.S.Tanenbaum, Operating System: Design and Implementation, Prentice Hall of India, 1989.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS348', 'Computer Networks', 'CSE', 'N/A', 'Prof. Bhaskaran Raman', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Design of Computer Networking protocols at all layers: transmission media, data link protocols, media access control, routing and congestion control, admission control, traffic shaping and policing, Internet working (IP) and transport layer protocols (TCP). Performance analysis of networks.', '1.W. Stallings, Data and Computer Communications, 6th edition, Prentice Hall, 2000. 2.A. S. Tannenbaum, Computer Networks, 4th edition, Prentice Hall, 2003. 3.F.Halsall, Data Communications, Computer Networks and Open Systems, 4th edition, Addison-Wesley. 4.Walrand and Varaiya, High Performance Communication Networks, Morgan Kaufman, 1996. 5.D. E. Comer, Internet working with TCP/IP: Principles, Protocols, Architecture, 3rd edition, Prentice Hall. 6.W. R. Stevens, TCP/IP Illustrated Vol. I, Addison Wesley, 1994.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS355', 'Programming Paradigms Laboratory', 'CSE', 'N/A', 'Prof. Manas Thakur', 'N/A', 'Autumn', '3', 'N/A', 'Full Semester', 'Lab', 'Programming abstractions; Functional programming; Object-oriented programming; Reasoning about programs with assertions; Implementation models for paradigms', 'Harold Abelson, Gerald Jay Sussman and July Sussman, Structure and Interpretation of Computer Programs, 2nd edition, The MIT Press, 1996. 2. David A. Watt, Programming Language Concepts and Paradigms, Prentice-Hall, 1990. 3. Rajeev Sangal, Programming Paradigms in Lisp, McGraw Hill, 1991.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS378', 'Computer Networks Lab', 'CSE', 'N/A', 'Prof. Bhaskaran Raman', 'N/A', 'Autumn', '3', 'N/A', 'Full Semester', 'Lab', 'Experiments to support study of the Internet protocol stack: (a) Understand the use of various command line tools like ping, arp, route, ifconfig, host, traceroute, dig etc. (b) Use packet sniffing tools like tcpdump, wireshark to understand various concepts: encapsulation/decapsulation; multiplexing demultiplexing, dhcp operation, IP fragmentation, ARP operation, ICMP operation, TCP operation, application protocols such as HTTP, FTP, SMTP.', 'N/A', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS405', 'Game Theory and Algorithmic Mechanism Design', 'CSE', 'N/A', 'Prof. Swaprava Nath', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Non-cooperative game theory - foundation for discussing mechanism design: quantitative models of strategic interaction (rationality, intelligence, common knowledge); complete information simultaneous move games - normal form representation (Nash equilibrium, existence results, complexity, correlated equilibrium); complete information sequential move games - extensive form representation (subgame perfect equilibrium, perfect Bayesian equilibrium); incomplete information games (Bayesian games, equilibria concepts). Introduction to mechanism design: incomplete information to player types; social welfare function, Arrow''s impossibility result; social choice function, Gibbard-Satterthwaite result; domain restriction; single-peaked preferences; task allocation domain; quasi-linear preferences. Real world applications of mechanism design.', 'No specific textbook. Useful references: Maschler, Solan and Zamir, Game Theory (2nd ed.), Cambridge University Press, 2020; Shoham and Leyton-Brown, Multiagent Systems: Algorithmic, Game-Theoretic, and Logical Foundations, Cambridge University Press, 2008; Osborne, An Introduction to Game Theory, Oxford University Press, 2009; Narahari, Game theory and mechanism design, World Scientific, 2014; Debasis Mishra, Game Theory and Mechanism Design course notes.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS409', 'Introduction to Cryptography', 'CSE', 'https://sruthisekar.wordpress.com/introduction-to-cryptography-m', 'Prof. Sruthi Sekar', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Perfectly secret encryption: one time pad, limitations of perfect security. Private key encryption: defining encryption CPA security, constructing CPA secure scheme - pseudorandom functions and block ciphers, pseudorandom generators, stream ciphers, one-way functions, hardcore predicates, CCA security, message authentication codes, some practical constructions. Hash Functions and applications. Public key encryption: CPA security, El Gamal, RSA and Rabin constructions, some attacks on RSA. Zero Knowledge Proofs: honest verifier zero knowledge, one protocol.', '1. Introduction to Modern Cryptography (Jonathan Katz and Yehuda Lindell, Third edition) Chapman and Hall, 2014. 2. The Joy of Cryptography (Mike Rosulek), 2021. 3. A Course in Cryptography (Rafael Pass and Abhi Shelat, Third edition). 4. A Graduate Course in Applied Cryptography (Dan Boneh and Victor Shoup, Version 0.6, Jan 2023). 5. Lecture notes for fundamentals of cryptography (Leonid Reyzin). 6. Foundations of Cryptography, Volume I-II, Oded Goldreich, Cambridge University Press, 2008', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS409M', 'Introduction to Cryptography', 'CSE', 'https://www.cse.iitb.ac.in/~ckamath/courses/2026a/CS409m.html', 'Prof. Chethan Kamath', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Cryptography is the science of securely carrying out tasks (e.g., communication) in presence of adversaries (e.g., eavesdroppers). In this course, we will first study certain basic tasks in cryptography (e.g., secure communication), with an emphasis on precise modelling of the adversary''s capabilities and goal -- the threat model -- and formally proving security in this model -- the security proof. Then, we will see how more complex applications you use everyday (e.g., HTTPS, secure messaging, one-time password) can be built on top of these. Additionally, we will also have hands-on sessions aimed at exposing you to real world cryptographic libraries.', '1. Introduction to Modern Cryptography (Jonathan Katz and Yehuda Lindell, Third edition) Chapman and Hall, 2014. 2. The Joy of Cryptography (Mike Rosulek), 2021. 3. A Course in Cryptography (Rafael Pass and Abhi Shelat, Third edition). 4. A Graduate Course in Applied Cryptography (Dan Boneh and Victor Shoup, Version 0.6, Jan 2023). 5. Lecture notes for fundamentals of cryptography (Leonid Reyzin). 6. Foundations of Cryptography, Volume I-II, Oded Goldreich, Cambridge University Press, 2008', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS416M', 'Foundations of Network Security and Cryptography', 'CSE', 'N/A', 'Prof. G. Sivakumar', 'N/A', 'Autumn', '6', 'CS 224 M', 'Full Semester', 'Theory', 'Vulnerabilities, risks, attacks, defences, forensics. Examples and applications of Public Key Cryptography and Secret Key Cryptography. Crypto hash, digital signatures, digital certificates and PKI. Basic Authentication and Key Agreement protocols, SSL/TLS and Kerberos. Vulnerabilities and attacks on TCP, DNS, ARP, etc. and DDoS attacks. Network/host intelligence gathering and reconnaissance methods. Web security - SQL injection, XSS, etc. Software security and buffer overflow. Malware types and case studies. Access Control, firewalls and host/network intrusion detection.', '1. Menezes, Bernard. Network Security And Cryptography, 1st ed., Cengage Learning India, 2010. 2. Stallings, William. Cryptography And Network Security, Fourth Edition, Pearson, 2006', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6001', 'Game Theory and Algorithmic Mechanism Design', 'CSE', 'https://www.cse.iitb.ac.in/~swaprava/cs6001_07_2023.html', 'Prof. Swaprava Nath', 'N/A', 'Autumn', '6', 'CS6001', 'Full Semester', 'Theory', 'Non-cooperative game theory - foundation for discussing mechanism design: quantitative models of strategic interaction; complete information simultaneous and sequential move games; incomplete information games (Bayesian games). Introduction to mechanism design: social welfare function, Arrow''s impossibility result; social choice function, Gibbard-Satterthwaite result; domain restriction; single-peaked preferences; task allocation domain; quasi-linear preferences. Real world applications of mechanism design.', 'No specific textbook. Useful references: Michael Maschler, Eilon Solan, Shmuel Zamir, Game Theory (2nd Edition), Cambridge University Press. Yoav Shoham and Kevin Leyton-Brown, Multiagent Systems (www.masfoundations.org). Martin Osborne, An Introduction to Game Theory, Oxford University Press. Y. Narahari, Game Theory and Mechanism Design, World Scientific. Debasis Mishra''s Game Theory and Mechanism Design course notes.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6007', 'Multi-Agent Machine Learning (MAML)', 'CSE', 'N/A', 'Prof. Avishek Ghosh', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'Theory', 'Module I: Federated Learning (FL) - Basic Formulation, FedAvg algorithm, Non-convexity. Challenges in FL: Heterogeneity, Communication Bottleneck, Adversarial Attacks, Data Privacy. Study of clustering in FL, local averaging and compression, robust estimators, and Differential Privacy. Module II: Multi Agent Bandits - Collaborative Multi Agent Multi Arm Bandits, Gossip Type Algorithms, Modified UCB, Regret Guarantees, Federated Bandits, Federated RL. Module III: Matching Markets - formulation via bipartite graph, stable matching, Gale-Shapley, preference learning via bandit framework, algorithms (CA-UCB, ETGS, UCBD3), dynamic/structured/robust market variations.', '1. Optimization for Data Analysis, Benjamin Recht and Stephen J. Wright, Cambridge University Press, 2022. 2. Optimization Algorithms for Distributed Machine Learning, Gauri Joshi, Springer, 2023. 3. Federated Learning: A Comprehensive Overview of Methods and Applications, Yaochu Jin, Hangyu Zhu, Jinjin Xu, Springer, 2022. 4. Bandit Algorithms, Csaba Szepesvari and Tor Lattimore, Cambridge University Press, 2020. 5. Learning Theory from First Principles, Francis Bach, MIT Press, 2024. Plus several research papers on FedAvg convergence, Byzantine-robust learning, and multi-agent bandits.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6008', 'Network Security', 'CSE', 'N/A', 'Prof. Devashish Gosain', 'N/A', 'Autumn', '6', 'Desired background: Knowledge of computer networks. CS224 for UGs', 'N/A', 'Theory', 'Module1: Network Background - Internet Protocol Stack, Link Layer technologies, Network Layer Protocols, Transport Layer Protocols, Popular Applications. Practical sessions with Wireshark, Scapy, and network commands. Module2: Network Attacks and Defenses at various layers, including DOS attacks. Module3: Secure Network Protocols - 802.1X, WEP/WPA, MAC-sec, IPsec, IKE, openVPN, TLS, SSH, DNSsec, Email Security, SNMP security. Module4: Network Hardening - Defense in depth, Vulnerability Scanners, Secure network topologies, Firewalls, IDS, Honeypots and Honeynets.', 'Network Security Essentials by William Stallings, Sixth edition. Internet Security: A Hands-on Approach by Wenliang Du, second edition. Network Security: Private Communications in a Public World, 3rd Edition, by Charlie Kaufman, Radia Perlman, et al. Plus tools: Wireshark, Scapy, OpenVAS, Snort, OSSEC.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS601', 'Algorithms and Complexity', 'CSE', 'https://sites.google.com/view/algorithms-cs-601/home', 'Prof. Akash Kumar', 'N/A', 'Autumn', '6', 'NIL', 'Full Semester', 'Theory', 'Techniques for the Design and Analysis of Algorithms. Formal models of computation, time and space complexity, Theory of NP-Completeness, Approximability of NP-Hard problems. Introduction to parallel, randomized and on-line algorithms.', 'J. Kleinberg and E. Tardos, Algorithm Design, Addison Wesley, 2005. T. H. Cormen, C. E. Leiserson, R. L. Rivest and C. Stein, Introduction to Algorithms, MIT Press and McGraw Hill, 3rd Edition, 2009. Rajeev Motwani, Prabhakar Raghavan, Randomized algorithms, Cambridge University Press, 1995. M. R. Garey and D. S. Johnson, Computers and Intractability: A Guide to the Theory of NP-Completeness, Freeman, 1979.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6010', 'Applied Cloud Computing', 'CSE', 'N/A', 'Prof. Kameswari Chebrolu', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'Theory', 'Introduction to cloud service and deployment models. Cloud Building Blocks: Data Centers, Compute Virtualization (VMs, Containers), Internet & Networking, Identity & Access Management, Storage Technologies, Distributed Systems. Cloud Operations: Cost awareness, Security basics, Observability, API-Driven Cloud. Emerging Trends: Hybrid multi-cloud, Serverless, Microservices, Edge computing. Hands-on component (AWS free-tier): launching VMs/Containers, IAM exploration, VPC setup, load balancers/CDNs, storage attachment, message queues.', 'No dedicated text book. References: Cloud Computing: Concepts, Technology & Architecture by Ricardo Puttini, Thomas Erl, and Zaigham Mahmood, 1e, 2014, Pearson Education. Practical Cloud Security: A Guide for Secure Design and Deployment, March 2019, by Chris Dotson, O''Reilly. The NIST Definition of Cloud Computing. Plus various technical papers on data center networks, virtualization, and object storage.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6011', 'Introduction to Cryptography', 'CSE', 'https://sruthisekar.wordpress.com/introduction-to-cryptography-m/', 'Prof. Sruthi Sekar', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'Theory', 'Perfectly secret encryption: one time pad, limitations of perfect security. Private key encryption: CPA security, pseudorandom functions and block ciphers, pseudorandom generators, stream ciphers, one-way functions, hardcore predicates, CCA security. Hash Functions and applications. Public key encryption: CPA security, El Gamal, RSA and Rabin constructions, attacks on RSA. Zero Knowledge Proofs.', '1. Introduction to Modern Cryptography (Jonathan Katz and Yehuda Lindell, Third edition) Chapman and Hall, 2014. 2. The Joy of Cryptography (Mike Rosulek), 2021. 3. A Course in Cryptography (Rafael Pass and Abhi Shelat, Third edition). 4. A Graduate Course in Applied Cryptography (Dan Boneh and Victor Shoup, Version 0.6, Jan 2023). 5. Lecture notes for fundamentals of cryptography (Leonid Reyzin). 6. Foundations of Cryptography, Volume I-II, Oded Goldreich, Cambridge University Press, 2008', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6012', 'Deep Learning: Foundations and Applications', 'CSE', 'N/A', 'Prof. Sharat Chandran', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'Theory', 'Ethics and societal aspects: privacy, data governance, explainability and transparency, environmental and societal impact. Basics: Function approximators, backpropagation, and automatic differentiation, loss functions, fitting models, measuring performance, regularization, supervised, unsupervised, and reinforcement learning. Architectures: CNNs, Residual networks, sequence models, attention, transformers, graph neural networks. Generative AI: GANs, Flows, autoencoders, diffusion models. Agentic AI, Multimodal learning, Large language models, Retrieval-augmented learning, representation learning, applications in computer vision, text systems, scientific domains.', 'Texts: 1. Simon J.D. Prince, Understanding Deep Learning, MIT Press, 2023. 2. Antonio Torralba, Phillip Isola, William T. Freeman, Foundations of Computer Vision, MIT Press, 2024. 3. Dan Hendrycks, Introduction to AI Safety, Ethics, and Society, 2024, Open Access. References: Ian Goodfellow, Yoshua Bengio, Aaron Courville, Deep Learning, MIT Press, 2016. Christopher M. Bishop, Deep Learning: Foundations and Concepts, Springer, 2023. Plus several other ethics/alignment references.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6013', 'Efficient AI', 'CSE', 'N/A', 'Prof. Aditya Desai', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Algorithmic approaches, including hardware-aware ones, to improve efficiency in AI inference and training: Model compression, Sparsity/pruning, Hardware support for sparsity/quantization, Elastic Parameter Memory, Hardware-aware hashing, Neural Architectural Search, Low-rank methods, PEFT techniques (LoRA and variants), Knowledge distillation, Sparse attention, Speculative decoding, KV cache compression, Semantic Prompt Caching, Attention alternatives (SSMs, Linear Attention), IR techniques in LLM inference, Context Extension and Compaction.', '1. Desai, A., 2024. Elastic Parameter Memory for Efficient Machine Learning (Doctoral dissertation, Rice University). 2. Frankle, J., 2023. The Lottery Ticket Hypothesis: On Sparse, Trainable Neural Networks (Doctoral dissertation, MIT). 3. Quang, T.D.P., 2023. Hardware-Aware Algorithms for Efficient Machine Learning, Stanford University. 4. Chen, B., 2020. Locality Sensitive Sampling for Extreme-Scale Optimization and Deep Learning (Doctoral dissertation, Rice University). Plus course materials and paper lists from MIT/Berkeley courses on efficient ML.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS602', 'Applied Algorithms', 'CSE', 'https://sites.google.com/view/cs-602-applied-algorithms-2025/home', 'Prof. Sujoy Bhore, Prof. Arpit Agarwal', 'N/A', 'Autumn', 'N/A', 'Basics of Algorithms and Data Structures (CS218/601), Discrete Math, Graph Theory, Linear Algebra', 'N/A', 'Theory', 'Rigorous and interactive introduction to the fundamental concepts and techniques of the modern algorithmic toolkit, emphasizing both theoretical foundations and practical application. Topics include: Metric Traveling Salesman Problem; Metric Steiner Tree; PTAS for Euclidean TSP; Metric Embeddings; Dimensionality reduction, Johnson-Lindenstrauss Lemma; Approximate Nearest Neighbor Searches; Clustering, Data Summarization; Load Balancing, VC dimension; Online Algorithms; Streaming Algorithms; Online Learning with MWU, and Convex Optimization.', 'The Design of Approximation Algorithms, David P. Williamson and David Shmoys. Approximation Algorithms, Vijay Vazirani. Randomized Algorithms, Rajeev Motwani and Prabhakar Raghavan. Online Computation and Competitive Analysis, Allan Borodin and Ran El-Yaniv. Data Streams: Algorithms and Applications, S. Muthukrishnan. Foundations of Data Science, Avrim Blum, John Hopcroft, Ravindran Kannan. Beyond the Worst-Case Analysis, Tim Roughgarden.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS604', 'Combinatorics', 'CSE', 'http://www.cse.iitb.ac.in/~cs604', 'Prof. Sundar Vishwanathan', 'N/A', 'Autumn', '6', 'NIL', 'N/A', 'N/A', 'Min-max results. Dilworth''s theorem, Hall''s theorem. Menger''s theorem. Topics on tournaments. Perfect graphs. The weak perfect graph theorem. Ramsey theory. Set Systems. Sperner, Erdos-Rado and the Erdos-Ko-Rado theorems. Colex orders and the Kruskal-Katona theorem. The probabilistic method. Second moment method and applications. Matroid theory. The theory of designs. Combinatorics and Algorithm design. The Lovasz-theta function and its use in designing algorithms.', 'K. R. Parthasarathy, Basic Graph Theory, Tata McGraw-Hill, 1994. B. Bollobas, Combinatorics, Cambridge University Press, 1986. I. Anderson, Combinatorics of finite sets, Oxford University Press, 1987. N. Alon and J. H. Spencer, The Probabilistic Method, John Wiley and Sons, 1992.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6101', 'Indexing and Retrieving Text and Graphs', 'CSE', 'N/A', 'Prof. Soumen Chakrabarti', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'This course replaces CS635, whose code had been reused for decades while the course was overhauled multiple times. Recent developments in deep retrieval necessitated an entirely new course. Classic inverted index for sparse retrieval; relevance ranking; learning to rank; latent semantic indexing and topic models; word embeddings; dense retrieval; locality sensitive hashing; graph proximity and matching; graph indexing and retrieval.', 'Ian H. Witten, Alistair Moffat, and Timothy C. Bell, Managing gigabytes: compressing and indexing documents and images, Morgan Kaufmann, 1999. Hinrich Schutze, Christopher D. Manning, and Prabhakar Raghavan, Introduction to information retrieval, Cambridge University Press, 2008. W. Bruce Croft, Donald Metzler, and Trevor Strohman, Search engines: Information retrieval in practice, Addison-Wesley, 2010. Mitra, Bhaskar, and Nick Craswell, An introduction to neural information retrieval, Foundations and Trends in Information Retrieval, 2018. Cook, Diane J., and Lawrence B. Holder (eds), Mining graph data, John Wiley & Sons, 2006. Xuan, Qi, Zhongyuan Ruan, and Yong Min (eds), Graph data mining, Springer, 2021.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS616', 'Parallelizing Compilers', 'CSE', 'http://www.cse.iitb.ac.in/~cs616', 'Prof. Milind Girkar', 'N/A', 'Autumn', '6', 'UG compilers course', 'Full Semester', 'Theory', 'Parallelizing Compilers - motivation and overview, structure of a parallelizing compiler; review of code optimization techniques in compilers for sequential machines. Parallelism detection - data dependence, direction vectors, loop carried and loop independent dependences; construction of data dependence graph. Control dependence and control dependence graph. Restructuring transformations and automatic extraction of parallelism; loop based transformations. Introduction to machine models and algorithms for parallel code generation and task graph construction. Interprocedural analysis. Partitioning and Scheduling of a task graph. Case studies of contemporary parallelising compiler efforts.', 'M. J. Wolfe, Optimizing Supercompilers for supercomputers, MIT Press, 1989. V. Sarkar, Partitioning and Scheduling Parallel Programs for Execution on Multiprocessors, MIT Press, 1989. U. Banerjee, Dependence Analysis for Supercomputing, Kluwer Academic Publishers, 1988.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS618', 'Program Analysis', 'CSE', 'N/A', 'Prof. Uday Khedker', 'N/A', 'Autumn', '6', 'First course in compiler construction.', 'Full Semester', 'Theory', 'Mathematical Foundations of Program Analysis: Lattices, function spaces, Fixed Point Computations, Abstract interpretation. Alias analysis of heap data: types of alias information, representations of heap properties, data flow analysis for aliases. Liveness analysis of heap data. Static type inferencing of flow sensitive polymorphic types. Inter procedural data flow analysis: context sensitive/insensitive analysis, functional approach, call strings approach.', 'Uday P. Khedker, Amitabha Sanyal, Bageshri Karkare, Data flow analysis: Theory and Practice, CRC Press (Taylor and Francis Group), 2009.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS631', 'Implementation Techniques for Relational Database Systems', 'CSE', 'http://www.cse.iitb.ac.in/infolab/Data/Courses/CS631', 'Prof. S Sudarshan', 'N/A', 'Autumn', '6', 'Nil', 'Full Semester', 'Theory', 'Physical storage and indexing structures, Query processing algorithms, Query optimization, Transaction processing and serializability, Concurrency Control, Recovery. Big data management: transaction and query processing on parallel and distributed databases including issues of availability, replication, consistency, concurrency control, and recovery. Emerging database trends.', 'Abraham Silberschatz, Henry F. Korth and S. Sudarshan, Database System Concepts 6th Ed, McGraw Hill, 2010. Transaction Processing, Concepts and Techniques, J. Gray and A. Reuter, Morgan Kauffman, 1994. Research papers from leading conferences and journals', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS632', 'Advanced Database Management Systems', 'CSE', 'http://www.cse.iitb.ac.in/dbms/Data/Courses/CS632/', 'Prof. Suraj Shetiya', 'N/A', 'Autumn', '6', 'CS 631', 'N/A', 'N/A', 'Based primarily on research papers covering: Top-k query processing including skylines, Fagin''s algorithm and quality of top-k. Materialized views and its implications in ranking. Advanced query optimization, including database tuning. Adaptive query processing and optimization; Transaction and query processing on main-memory and columnar databases; Data streams and stream management systems; Handling uncertain data. ML based techniques applied to these problems, including fairness in ranking and selection.', 'Textbooks: Abraham Silberschatz, Henry F. Korth and S. Sudarshan, Database System Concepts 7th Ed, McGraw Hill, 2020. Barocas, Solon, Moritz Hardt, and Arvind Narayanan, Fairness and machine learning: Limitations and opportunities, MIT press, 2023. Plus numerous research papers on top-k queries, fairness-aware ranking, and B-tree techniques.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS663', 'Fundamentals of Digital Image Processing', 'CSE', 'N/A', 'Prof. Suyash P. Awate', 'N/A', 'Autumn', 'N/A', 'Linear algebra, probability and statistics, data structures and algorithms, computing', 'N/A', 'Theory + Lab', 'Mathematical theory, algorithms, and computational aspects of fundamental topics in image processing and analysis, including principles from machine learning and deep learning, with hands-on computing experiments (Python/Matlab). Topics: image acquisition and representation; basic operations and intensity transformations; spatial filtering; image segmentation; image restoration; frequency-domain processing; image compression; morphological image processing; PCA in image processing (eigenfaces); deep learning for image processing.', 'Introduction to Mathematical Statistics (Hogg, McKean, Craig). Introduction to Probability and Statistics for Engineers and Scientists (Ross). Introduction To Linear Algebra (Strang). Applied Numerical Linear Algebra (Demmel). Digital Image Processing: An Algorithmic Introduction (Burger, Burge). Digital Image Processing (Gonzales, Woods). Fundamentals of Digital Image Processing (Jain).', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS675', 'Computer Graphics', 'CSE', 'https://www.cse.iitb.ac.in/~paragc/course/2025-02-cs675/', 'Prof. Parag Chaudhuri', 'N/A', 'Autumn', '6', 'Data Structures, Linear Algebra, Proficiency in programming with C++', 'Full Semester', 'Theory + Project', 'Rasterization of lines and circles, Clipping algorithms; Synthetic Camera and Image formation models; 2D and 3D transformations; The Modelling-Viewing Pipeline; Visibility; Ray Tracing; Shading and Illumination models; Texture Mapping; Curves and Surfaces; Hierarchical Modelling, Animation.', 'Interactive Computer Graphics: A topdown approach using OpenGL, 5th ed., Edward Angel, Pearson Education. Computer Graphics using OpenGL, 3rd ed., F. S. Hill Jr. and S. M. Kelley, Pearson Education. Computer Graphics with OpenGL, 3rd ed., D. D. Hearn and M. P. Baker, Pearson Education. Fundamentals of Computer Graphics, 3rd ed., Peter Shirley, A K Peters, 2009.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS683', 'Advanced Computer Architecture', 'CSE', 'https://www.cse.iitb.ac.in/~biswa/courses/CS683/main.html', 'Prof. Biswabandan Panda', 'N/A', 'Autumn', '6', 'NIL', 'Full Semester', 'Theory', 'Superscalar and out-of-order processors, microarchitecture techniques to improve processor performance. Advanced caches: multicore caches, cache coherence protocols, techniques to improve memory hierarchy performance, memory hierarchy for scalable multicore design. Introduction to SIMD processors, GPUs, and accelerators like TPUs. Microarchitecture security and architecture tradeoffs in terms of performance, power, and security', '1. Computer Architecture: A Quantitative Approach, J. Hennessy and D. Patterson, Morgan Kaufmann, 5th edition onwards. 2. Parallel Computer Architecture: A Hardware/Software Approach, David Culler and Jaswinder Pal Singh, Morgan Kaufmann', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS691', 'R & D Project I (M.Tech)', 'CSE', 'N/A', '---', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS694', 'Seminar ( M.Tech./MSR)', 'CSE', 'N/A', 'N/A', 'N/A', 'Autumn', '4', '0', 'N/A', 'N/A', 'N/A', 'N/A', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS699', 'Software Lab.', 'CSE', 'http://10.105.1.20/moodle/course/view.php?id=6', 'Prof. Om Damani', 'N/A', 'Autumn', '8', 'NIL', 'Full Semester', 'Lab', 'Vim/emacs, HTML, CSS. Preparing reports and presentations using latex, beamer, drawing software, and graph plotting software. Programming support: IDE, Makefile, debugging tools, profiling tools, version management, code review. Basic Java, Java collections, interfaces. Unix basics: shell, file system, permissions, process hierarchy, process monitoring, ssh, rsync. Unix tools: awk, sed, grep, find, head, tail, tar, cut, sort, Bash scripting. Programming using scripting language (e.g. python). Lexical analysis and parsing tools (e.g. lex/yacc, flex/bison). Optional topics: sockets, basic SQL for data storage, JDBC/pygresql, PHP, mobile apps. Includes a project (20-30 hours) touching upon many of these topics.', 'Online tutorials for HTML/CSS, Inkscape, OODraw. Unix Man Pages, Advanced Bash Scripting Guide from the Linux Documentation Project. The Python Tutorial Online Book. The Java Tutorials. Latex - A document preparation system, Leslie Lamport, 2/e, Addison-Wesley, 1994', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS7001', 'Robot Perception and Learning', 'CSE', 'N/A', 'Prof. Nived Chebrolu', 'N/A', 'Autumn', '8', 'N/A', 'N/A', 'Theory', 'Foundational principles of probabilistic robotics and learning-based control: Recursive State Estimation; Mobile Robot Localization using Kalman Filter and Particle Filter; Robot Motion and Sensor Models; Mapping techniques (Occupancy Grid Mapping); SLAM variants (EKF-SLAM, Graph-SLAM, Particle Filter SLAM); Scene Exploration Algorithms; Planning under uncertainty using MDPs, POMDPs; Robot learning from demonstrations (Imitation learning, Behaviour Cloning); Reinforcement learning for robot control; Generative models for control.', '1. Probabilistic Robotics, Sebastian Thrun, Wolfram Burgard, and Dieter Fox, MIT Press, 2005. 2. Introduction to Autonomous Mobile Robots, Roland Siegwart, Illah Reza Nourbakhsh and Davide Scaramuzza, 2nd Edition, MIT Press, 2011. 3. SLAM Handbook: From Localization and Mapping to Spatial Intelligence, Luca Carlone et al, Cambridge University Press, 2025. 4. Robotics, Vision and Control, Peter Corke, Springer 3rd Edition, 2023. 5. Reinforcement Learning: An Introduction, Richard S. Sutton and Andrew G. Barto, 2nd edition, MIT Press, 2018', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS721', 'Introduction to Computational Complexity', 'CSE', 'https://www.cse.iitb.ac.in/~vishwas/cs721.html', 'Prof. Vishwas Bhargava', 'N/A', 'Autumn', '6', 'Good undergraduate background in Theory of Computation (CS331 or Automata and Logic CS208), Design and Analysis of Algorithms (CS301 or CS218) or equivalent.', 'Full Semester', 'Theory', 'Overview of computability: Church-Turing thesis, decidability, reducibility, recursion theorem. Time and space complexity: classes P, NP, P vs NP, NP-completeness, Cook-Levin Theorem, Savitch''s Theorem, PSPACE completeness, classes L, NL. Alternation, polynomial time hierarchy. Intractability: hierarchy theorems, relativization, circuit complexity. Parallel Complexity, Probabilistic Complexity, Interactive Proofs: NC, BPP, IP=PSPACE. Probabilistically Checkable Proofs and hardness of approximation. The Arithmetic Hierarchy, Post''s problem, Friedburg-Muchnik Theorem.', 'M. R. Garey and D. S. Johnson, Computers and Intractability, Freeman and Company, 1979. J. L. Balcazar, J. Diaz and J. Gabarro, Structural Complexity I and II, Springer. C. Pappadimitriou, Computational Complexity, Addison-Wesley, 1994. Dexter Kozen, Automata and Computability, Springer, 1997. Mike Sipser, Introduction to the Theory of Computation, PWS Publishing Company, 1997. J. E. Hopcroft, R. Motwani, and J. D. Ullman, Introduction to Automata Theory, Languages, and Computation, 2nd Edition, 2001. Sanjeev Arora and Boaz Barak, Computational Complexity: A Modern Approach, Cambridge University Press, 2009.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS725', 'Foundations of machine learning', 'CSE', 'https://www.cse.iitb.ac.in/~sunita/cs725/index.html', 'Prof. Sunita Sarawagi', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Remedial co-requisite: Mathematical foundations. Recommended parallel course: CS709 (Convex optimization). Supervised learning: decision trees, nearest neighbor classifiers, generative classifiers (naive Bayes, LDA), loss regularization framework for classification, Support Vector Machines. Regression methods: least-square regression, kernel regression, regression trees. Unsupervised learning: k-means, hierarchical, EM, non-negative matrix factorization, rate distortion theory.', 'Understanding Machine Learning, Shai Shalev-Shwartz and Shai Ben-David, Cambridge University Press, 2017. The Elements of Statistical Learning, Trevor Hastie, Robert Tibshirani and Jerome Friedman, 2nd Edition, 2009. Pattern Recognition and Machine Learning, Christopher Bishop, Springer, 2006. Foundations of Data Science, Avrim Blum, John Hopcroft and Ravindran Kannan, 2017.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS740', 'Mathematics for Visual Computing', 'CSE', 'https://www.cse.iitb.ac.in/~ajitvr/CS740_Fall2026/', 'Prof. Ajit Rajwade', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Subset of topics from: Multivariate Calculus (functions and derivatives, Taylor series, matrix calculus, vector calculus); Numerical Linear Algebra (special matrices, matrix decompositions - SVD, eigen analysis); Probability and Statistics (distributions, mean, variance, covariance, bounds, likelihood function, Bayes rule, entropy, divergence, mutual information); Optimization (unconstrained - gradient descent, Newton''s method, Levenberg-Marquardt algorithm, quasi-Newton methods; constrained - equality constraints, Lagrange multipliers).', '1. Numerical Recipes - The Art of Scientific Computing, William H. Press, Saul A. Teukolsky, William T. Vetterling, Brian P. Flannery, Cambridge University Press, 2007. 2. Scientific Computing, Michael T. Heath, McGraw-Hill, 2002. 3. Numerical Linear Algebra, Lloyd N. Trefethen, David Bau III, SIAM, 1997. 4. A First Course in Probability, Sheldon Ross, Pearson Education, 2012. 5. Probability, Random Variables and Stochastic Processes, Athanasios Papoulis, S. Unnikrishna Pillai, McGraw-Hill, 2002. 6. Numerical Optimization, Jorge Nocedal, Stephen Wright, Springer, 2006. 7. Elements of Information Theory, Thomas M. Cover, Joy A. Thomas, Wiley-Interscience, 2006', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS744', 'Design and Engineering of Computing Systems', 'CSE', 'N/A', 'Prof. Purushottam Kulkarni', 'N/A', 'Autumn', '6', 'Undergraduate level familiarity with Data Structures and Programming, Computer Networks and Operating Systems', 'Full Semester', 'Theory', 'CPU scheduling, process management and inter-process communication, memory management, thread-safe programming, synchronization and concurrency control, synchronous and asynchronous I/O access mechanisms, design and implementation of scalable distributed systems, metrics for evaluation, tools and techniques for measurement, profiling and analysis of systems. Taught through exercises and assignments involving design, implementation and evaluation of applications such as web server, file server, game engine etc.', 'Operating System Principles: Silberschatz, Gavin and Gagne, Wiley, 8th Edition, 2008. Linux System Programming, Robert Love, O''Reilly Media, 2nd Edition, 2013. Advanced Programming in the UNIX Environment, W. Richard Stevens, Stephen A. Rago, Addison-Wesley Professional, 3rd edition, 2013. Distributed Systems (Concepts and Design), Colouris et al, Addison Wesley, 5th edition, 2011. The Art of UNIX Programming, Eric S. Raymond, Addison-Wesley, 2003. Operating Systems - A Concept Based Approach, D. M. Dhamdhere, Tata McGraw-Hill, 3rd Edition, 2012', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS767', 'Theoretical Machine Learning', 'CSE', 'N/A', 'Prof. Arpit Agarwal', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'A large collection of topics, of which a subset (2-3 modules) is covered per offering. Module I: PAC learning, statistical learning theory, VC dimension. Module II: Online algorithms, bandit algorithms, dimensionality reduction, sketching/streaming algorithms, boosting. Module III: theoretical aspects of deep learning. Module IV: support vector machines, convex optimization, non-negative matrix factorization, tensors in ML, stochastic block models. Module V: learning constant depth Boolean circuits, learning from natural proofs, computational limits to learnability. Module VI: connections to game theory and coding theory.', 'Understanding Machine Learning: From theory to algorithms, Shai Shalev-Schwartz and Shai Ben-David, Cambridge University Press, 2014. An introduction to computational learning theory, M J Kearns and U Vazirani, MIT Press, 1994. Algorithmic aspects of Machine learning, Ankur Moitra, 2014. Theory of Machine learning lecture notes, Elad Hazan, Princeton, 2015. Beyond worst case analysis in Machine Learning lecture notes, Pranjal Awasthi, Rutgers, 2016', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS769', 'Optimization in Machine Learning', 'CSE', 'N/A', 'Prof. Ganesh Ramakrishnan', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'Theory', 'Continuous Optimization with ML applications: Convexity, Gradient Methods, Proximal algorithms, Stochastic and Online Variants, Coordinate Descent, Subgradient Methods, Non-Convex Optimization, Frank-Wolfe, Accelerated Methods, Lagrange and Fenchel Duality, Second-Order and Quasi-Newton Methods, Gradient-Free Optimization. Discrete Optimization: combinatorial optimization (knapsack, s-t cuts/paths, matchings, matroids), submodular functions and applications, submodular minimization/maximization, Determinantal Point Processes. Applications in feature selection, summarization, structured prediction, data subset selection, model compression.', '1) Sebastien Bubeck, Convex Optimization: Algorithms and Complexity, Foundations and Trends in Machine Learning 8(3-4): 231-357. 2) Zhang, Aston, et al, Dive into Deep Learning, Chapter 11. 3) Bach, Francis, Learning with submodular functions: A convex optimization perspective, Foundations and Trends in Machine Learning 6.2-3 (2013). 4) Boyd, Stephen, and Lieven Vandenberghe, Convex optimization, Cambridge University Press, 2004. 5) Yurii Nesterov, Introductory lectures on convex optimization, 2004. 6) Schrijver, Alexander, A course in combinatorial optimization, CWI, 2003. 7) Schrijver, Alexander, Combinatorial optimization: polyhedra and efficiency, Springer, 2003. 8) Fujishige, Satoru, Submodular functions and optimization, Elsevier, 2005', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS771', 'Foundations of verification and automated reasoning', 'CSE', 'N/A', 'Prof. Paritosh Pandya', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Module 1: Logic - Propositional logic (syntax and semantics, truth table, satisfiability proof systems, equivalences, normal forms, tseitin encoding); FOL (syntax and semantics, SAT problem in FOL, proof systems, FOL Theories); simple programming language semantics, Hoare logic, invariants; SAT solvers (CDCL) and SMT solvers. Module 2: Automata - Linear temporal logic (LTL) and Computation tree logic (CTL); Automata on finite words (DFA/NFA, subset construction, pumping lemma); Automata on infinite words (Buchi automaton, omega-regular languages, NBA equivalence to LTL); Computability, Turing machines, decidability.', '(a) M. Huth and M. Ryan, Logic in Computer Science: Modeling and Reasoning about Systems, Cambridge University Press, 2004. (b) D. Kroening and O. Strichman, Decision Procedures: An Algorithmic Point of View, 2nd edition, Springer 2017. (c) Javier Esparza, Lecture Notes on Automata Theory: An Algorithmic Approach, 2017. (d) A. Robinson (Editor) et al, Handbook of Automated reasoning, North Holland, 2001. (e) Z3 source code, github.com/Z3Prover/z3, 2020', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS777', 'R & D Project I (MSR)', 'CSE', 'N/A', 'N/A', 'N/A', 'Autumn', '8', 'N/A', 'N/A', 'N/A', 'N/A', 'N/A', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS782', 'Algebra and Computation', 'CSE', 'N/A', 'Prof. Milind Sohoni', 'N/A', 'Autumn', '6', 'N/A', 'N/A', 'Theory', 'Algorithms for fast polynomial evaluation, polynomial multiplication, division with remainder, GCD of polynomials, Resultant and properties. Algorithms for polynomial factorization and applications. Lattices, Shortest vector problem, LLL algorithm and applications. Number theoretic algorithms (GCD, solving linear systems over integers, rational approximation of irrational numbers). Algorithms for integer factorization; Shor''s algorithm for integer factorization on quantum computers. Algorithms for primality testing (randomized and deterministic). Computational algebraic geometry, Ideal Membership problem, degree bounds, Groebner basis based methods. Algebraic independence, Jacobian and applications. Topics in algebraic complexity theory.', 'Modern Computer Algebra, Gerhard and von zur Gathen, Cambridge University Press, 2013. Computational Introduction to Number Theory and Algebra, Victor Shoup, Cambridge University Press, 2008. Finite Fields, Lidl and Niederreiter, Cambridge University Press, 1996. Equations over finite fields by Schmidt, Springer, 1976', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS787', 'Language Engineering for Complex Programs: A C++ Perspective', 'CSE', 'N/A', 'Prof. Rushikesh Joshi', 'N/A', 'Autumn', '6', 'N/A', 'Full Semester', 'Theory', 'Language engineering and design features of C++ for complex programs, applied to systems software and tools. (i) Components and modularity: Namespaces, Koenig lookup, scoping rules, initializers, constructors/destructors, separate compilation, libraries, errors and exceptions. (ii) Functions and control: Overloading and operator cascading, Lambda functions, parameter passing models, iterators, dynamic dispatch. (iii) Concurrency and distributed programming: Threading, Synchronization. (iv) Generic Programming: templates, standard template library, variadic templates, template metaprogramming. (v) Data, streams and conversions: type inferencing, type-safety, memory models, containers, file/string streams. (vi) Patterns and compositions: Design pattern implementations (Strategy, Prototype, Builder, Visitor, Composite, Adapter, Proxy, Observer, Iterator). (vii) Advanced Applications in C++: systems software including distributed publisher-subscriber event services, model translators, interpreters and execution engines.', '1) B. Stroustrup, A Tour of C++ (3rd Edition), Addison-Wesley, 2022. 2) Gamma, Helm, Johnson, Vlissides, Design Patterns: Elements of Reusable Object-Oriented Software, Addison-Wesley, 1994. 3) B. Stroustrup, The C++ Programming Language (Fourth Edition), Addison Wesley, 2013. 4) ISO/IEC Standard for Programming Language C++, 2020.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');


INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS108', 'Software Systems Lab', 'CSE', 'N/A', 'N/A', 'Prof. R.K. Joshi', 'Spring', '6', 'N/A', 'Full Semester', 'Lab', 'N/A', 'N/A', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS213M', 'Data Structures and Algorithms', 'CSE', 'N/A', 'N/A', 'Prof. Milind Sohoni', 'Spring', '6', 'CS 101', 'Full Semester', 'Theory', 'Introduction to data structures, abstract data types, analysis of algorithms. Creation and manipulation of data structures: arrays, lists, stacks, queues, trees, heaps, hash tables, balanced trees, tries, graphs. Algorithms for sorting and searching, order statistics, depth-first and breadth-first search, shortest paths and minimum spanning tree.', '1. T. Cormen, C. Leiserson, R. Rivest, C. Stein, Introduction to Algorithms, 2nd edition, Prentice-Hall India, 2001.
2. S. Sahni, Data Structures, Algorithms and Applications in C++,2nd edition, Universities Press,2005.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS217', 'Artificial Intelligence and Machine Learning', 'CSE', 'N/A', 'N/A', 'Prof. Avishek Ghosh', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Search: uninformed search, A* search, adversarial search, local search. Planning: Markov Decision Problems, Value Iteration and Policy Iteration. Probabilistic reasoning: Bayes nets, conditional independence, exact and approximate inference. Supervised learning: linear methods for classification and regression, regularisation, cross-validation, decision trees, neural networks, ensemble methods. Unsupervised learning: k-means clustering. Selected topics from natural language processing, robotics, computer vision, multi-agent systems.', 'Russell and Norvig, Artificial Intelligence: A Modern Approach, 3rd edition, Pearson, 2010. Poole and Mackworth, Artificial Intelligence: Foundations of Computational Agents, 3rd edition, 2023. Hastie, Tibshirani and Friedman, The Elements of Statistical Learning, 2nd Edition, 2009. Bishop, Pattern Recognition and Machine Learning, 2016. Goodfellow, Bengio and Courville, Deep Learning, MIT Press, 2016.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS218', 'Design and Analysis of Algorithms', 'CSE', 'N/A', 'N/A', 'Prof. Sujoy Bhore', 'Spring', '6', 'N/A', 'Full Semester', 'Theory', 'Models of computation, algorithm analysis, time and space complexity, average and worst case analysis, lower bounds. Algorithm design techniques: divide and conquer, greedy, dynamic programming, amortization, randomization. Problem classes P, NP, PSPACE; reducibility, NP-hard and NP-complete problems. Approximation algorithms for some NP-hard problems.', 'Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms, 2nd edition, Prentice-Hall India, 2001. Kleinberg and Tardos, Algorithm Design, Pearson International Edition, 2005.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS219', 'Operating Systems', 'CSE', 'N/A', 'N/A', 'Prof. Purushottam S. Kulkarni', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Introduction to operating systems: application requirements, the systems stack and role of OS, abstractions, interfaces, resource management, hardware architecture basics. Processes and process management: system call interface, process abstraction, user/kernel modes, inter-process communication, CPU scheduling fundamentals. Memory management: virtual memory, demand paging, memory management policies. Concurrency and synchronization: synchronization primitives, user vs kernel space concurrency. Filesystems: persistence, file abstraction, device management, filesystem design principles.', 'Arpaci-Dusseau and Arpaci-Dusseau, Operating Systems: Three Easy Pieces (pages.cs.wisc.edu/~remzi/OSTEP/). xv6 teaching OS (github.com/mit-pdos/xv6-public). Silberschatz, Galvin and Gagne, Operating Systems Concepts. Stallings, Operating Systems: Internals and Design Principles. Tanenbaum and Bos, Modern Operating Systems.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS224M', 'Computer Networks', 'CSE', 'N/A', 'N/A', 'Prof. Bhaskaran Raman', 'Spring', '6', 'N/A', 'N/A', 'N/A', 'Design of computer networking protocols at all layers: transmission media, data link protocols, media access control, routing and congestion control, admission control, traffic shaping and policing, internetworking (IP) and transport layer protocols (TCP). Performance analysis of networks.', 'Stallings, Data and Computer Communications, 6th edition, Prentice Hall, 2000. Tanenbaum, Computer Networks, 4th edition, Prentice Hall, 2003. Halsall, Data Communications, Computer Networks and Open Systems, 4th edition, Addison-Wesley. Walrand and Varaiya, High Performance Communication Networks, Morgan Kaufmann, 1996. Comer, Internetworking with TCP/IP, 3rd edition, Prentice Hall. Stevens, TCP/IP Illustrated Vol. I, Addison Wesley, 1994.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS236', 'Operating Systems Lab', 'CSE', 'N/A', 'N/A', 'Prof. Purushottam S. Kulkarni', 'Spring', '3', 'N/A', 'N/A', 'Lab', 'Exercises for use and appreciation of operating system concepts such as process management, process synchronization, memory management, file systems etc. Design and implementation of operating system functionalities using xv6, a teaching OS. Lab assignments involve writing simple programs using Linux system call APIs, and exploring/extending the internals of xv6.', 'xv6, a simple Unix-like teaching operating system (github.com/mit-pdos/xv6-public).', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS240', 'Artificial Intelligence and Machine Learning (Lab)', 'CSE', 'N/A', 'N/A', 'Prof. Avishek Ghosh', 'Spring', '3', 'N/A', 'N/A', 'Lab', 'Search: uninformed search, A* search. Planning: Markov Decision Problems, Value Iteration and Policy Iteration. Probabilistic reasoning: Bayes nets, conditional independence, exact and approximate inference. Supervised learning: linear methods for classification and regression, regularisation, cross-validation, decision trees, neural networks, ensemble methods. Unsupervised learning: k-means clustering.', 'Russell and Norvig, Artificial Intelligence: A Modern Approach, 3rd edition, Pearson, 2010. Hastie, Tibshirani and Friedman, The Elements of Statistical Learning, 2nd edition, Springer, 2009.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS306', 'Implementation of Programming Languages Lab', 'CSE', 'N/A', 'N/A', 'Prof. Uday Khedkar', 'Spring', '3', 'N/A', 'N/A', 'Lab', 'Design and implementation of a compiler for a sufficiently rich subset of a real programming language, automatically generated using tools such as LEX and YACC. Assignments cover parsing, AST construction, 3-address code generation, and code generation.', 'N/A', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS310M', 'Automata Theory', 'CSE', 'N/A', 'N/A', 'Prof. G. Sivakumar', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Finite state machines (DFA/NFA/epsilon NFAs), regular expressions, properties of regular languages, Myhill-Nerode theorem, non-regularity, push down automata, properties of context-free languages, Turing machines, Turing hypothesis, Turing computability, nondeterministic/multi-tape Turing machines, Church`s thesis, recursively enumerable sets, universal Turing machines, unsolvability, the halting problem, partial solvability, Turing enumerability, acceptability and decidability, Post`s correspondence problem.', 'Kozen, Automata and Computability, Springer, 1997. Hopcroft, Motwani and Ullman, Introduction to Automata Theory, Languages and Computation, Pearson Education Asia, 2006.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS317', 'Database and Information Systems', 'CSE', 'N/A', 'N/A', 'Prof. S. Sudarshan', 'Spring', '6', 'CS 213', 'N/A', 'Theory', 'Overview of data management systems. Relational model and query languages (relational algebra and calculus, SQL). Database design using the ER Model, ER Diagrams, UML Class Diagrams. Relational database design and normalization. Integrity and security. Design and development of web-based information systems. Overview of storage structures, indexing, query processing/optimization, and transaction processing. Introduction to big data management: distributed and scalable data storage, key-value stores, column stores, graph databases, replication and consistency, MapReduce. Introduction to decision support, data warehousing, data mining, and information retrieval.', 'Silberschatz, Korth and Sudarshan, Database System Concepts, 6th Ed, McGraw Hill, 2010.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS320', 'Implementation of Programming Languages', 'CSE', 'N/A', 'N/A', 'Prof. Uday Khedkar', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Compiled and interpreted execution models. Lexical analysis and parsing using lex and yacc. Scope and visibility analysis. Type analysis, binding times. Data layout and lifetime management, stack and heap storage structures. Implementation of function calls and activation records. Implementation of control structures, exception handling, and object-oriented concepts (objects, inheritance, dynamic dispatch). Implementation of a naive code generator for a virtual machine.', 'Aho, Lam, Sethi and Ullman, Compilers: Principles, Techniques, and Tools, 2/E, Addison-Wesley, 2007. Appel, Modern Compiler Implementation in C/ML/Java, Cambridge University Press, 2004. Grune, Bal, Jacobs and Langendoen, Modern Compiler Design, Wiley, 2000. Scott, Programming Language Pragmatics, Morgan Kaufmann, 2006.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS433', 'Automated reasoning', 'CSE', 'https://www.cse.iitb.ac.in/~akg/courses/2024-ar/', 'N/A', 'Prof. Ashutosh Kumar Gupta', 'Spring', '6', 'Nil', 'N/A', 'N/A', 'Design and implementation of solvers for proving/disproving validity of statements in various logics (reasoning engines). Covers satisfiability solvers, satisfiability modulo theories solvers, decision procedures for theories, first order logic solvers, and interactive theorem provers, including encoding problems into these solvers, efficient heuristics, implementation issues, and theoretical understanding. Includes programming assignments/projects. Open to PG and UG students.', 'Hedman, A First Course in Logic. Fitting, First-Order Logic and Automated Theorem Proving. Knuth, The Art of Computer Programming, Section 7.2.2.2 (Beta). Coq tutorial. Biere et al (eds), Handbook of Satisfiability. Robinson et al (eds), Handbook of Automated Reasoning. Gu et al, Algorithms for the Satisfiability (SAT) Problem. Andersen, Introduction to BDDs. Z3 source code.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6002', 'Selected Areas of Mechanism Design', 'CSE', 'https://www.cse.iitb.ac.in/~swaprava/cs6002_01_2023.html', 'N/A', 'Prof. Swaprava Nath', 'Spring', '6', 'CS6001', 'N/A', 'Theory', 'Selected topics in mechanism design: stable matching, Internet advertising, sponsored-search auctions, selfish routing, games on networks, potential games. Research-oriented course; students read and present cutting-edge research and develop a formal technical report. Part 1: mechanism design basics recap, cooperative game theory, stable matching theory, quasi-linear domain (Internet advertising, auctions, single-parameter domains), fair division, algorithmic aspects of mechanism design, network games. Part 2: selected papers from leading conferences/journals on mechanism design in AI and multi-agent systems.', 'No specific textbook. Osborne and Rubinstein, A Course in Game Theory, MIT Press, 1994. Brandt, Conitzer, Endriss, Lang and Procaccia (eds), Handbook of Computational Social Choice, Cambridge University Press, 2016. Roughgarden, Lecture Notes on Algorithmic Game Theory, Stanford CS364A, 2013. Mas-Colell, Whinston and Green, Microeconomic Theory, Oxford University Press, 1995. Debasis Mishra`s Game Theory and Mechanism Design course notes. Papers from EC, WINE, AAAI, IJCAI, AAMAS, Econometrica, Journal of Economic Theory, Games and Economic Behavior.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6003', 'Web security', 'CSE', 'N/A', 'N/A', 'Prof. Kameswari Chebrolu', 'Spring', '6', 'N/A', 'Full Semester', 'Theory', 'Module 1: Web background (history, web page structure, browser internals, protocols, session management, web security landscape), with practical sessions on Wireshark, browser dev tools, and OWASP ZAP. Module 2: Server side attacks and defense (SQL injection, SSRF, information disclosure, command injection, file upload vulnerabilities, authentication/authorization, path traversal, API vulnerabilities, server side template injection, DOS attacks). Module 3: Client side attacks and defense (CSRF, CORS, XSS, web sockets, clickjacking). Module 4: Miscellaneous topics as time permits (privacy, third-party code, web LLM attacks, HTTP parameter pollution, subdomain takeover).', 'Du, Computer Security: A Hands-on Approach, 3rd edition, 2022 (Part II on web security). McDonald, Web Security for Developers: Real Threats, Practical Defense, No Starch Press, 2020. Yaworski, Real-World Bug Hunting: A Field Guide to Web Hacking, No Starch Press, 2019. Plus web references: PortSwigger Web Security Academy, OWASP, MDN Web Docs, OWASP ZAP docs.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6009', 'Quantum Computing', 'CSE', 'N/A', 'N/A', 'Prof. Rohit Gurjar', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'State space and vector spaces; qubits, operations on a quantum system, entanglement, and measurement; Bell`s inequality; classical and quantum circuits; the no-cloning theorem and universal sets of gates; Deutsch-Jozsa and Bernstein-Vazirani algorithms; Grover`s search algorithm, amplitude amplification, and phase estimation; the quantum Fourier transform and its applications including integer factoring; quantum error correction; programming using quantum simulators.', 'Nielsen and Chuang, Quantum Computation and Quantum Information, Cambridge University Press, 2000. Kaye, Laflamme and Mosca, An Introduction to Quantum Computing, Oxford University Press, 2007. Kitaev, Shen and Vyalyi, Classical and Quantum Computation, American Mathematical Society, 2002. Mermin, Quantum Computer Science: An Introduction, Cambridge University Press, 2007. Aaronson, Quantum Computing Since Democritus, Cambridge University Press, 2013.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6102', 'Implementation Security in Cryptography', 'CSE', 'N/A', 'N/A', 'Prof. Sayandeep Saha', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'A 14-week course covering: introduction to cryptography and finite fields; implementation of modular exponentiation and Verilog basics; implementation of symmetric ciphers (composite field representation, S-Boxes, bitsliced implementation); timing/power side-channel attacks and leakage sources; power analysis (difference of means, correlation power attack, mutual information attack, template attacks); leakage assessment (TVLA); power attack countermeasures (random delay, shuffling, masking, threshold implementation, non-interference); fault attacks (differential fault attack, FSA, SIFA, FTA, countermeasures, PQC case study); microarchitectural impacts on power and fault attacks; supply chain security (hardware Trojans, logic locking, PUFs).', 'Mukhopadhyay and Chakraborty, Hardware Security: Design, Threats, and Safeguards, CRC, 2014. Mangard, Oswald and Popp, Power Analysis Attacks: Revealing the Secrets of Smart Cards, Springer, 2007. Daemen and Rijmen, The Design of Rijndael: AES - The Advanced Encryption Standard, Springer, 2002. Palnitkar, Verilog HDL: A Guide to Digital Design and Synthesis, 2nd ed, Prentice Hall, 2003. Stinson and Paterson, Cryptography: Theory and Practice, 4th ed, 2018. Plus research papers from TCHES, EUROCRYPT, ASIACRYPT, CRYPTO, DATE, DAC, ICCAD, HOST, ACM-CCS, S&P, USENIX Security.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6103', 'Human-Centered AI: From Learning Models to Responsible Systems', 'CSE', 'N/A', 'N/A', 'Prof. Arpit Agarwal', 'Spring', '6', 'N/A', 'Full Semester', 'Theory', 'Part 1 (Learning from Humans): crowdsourcing for machine learning, aggregating noisy human labels, active learning, learning with implicit/relative feedback (learning to rank, recommendation), introduction to causality (causal diagrams, effect estimation), strategic behavior modeling, human-in-the-loop learning and decision-making. Part 2 (Responsible AI for Humans): fairness and diversity metrics and bias mitigation, privacy (differential privacy, privacy-utility tradeoffs), interpretability and explainability, recommendation systems and feedback loops, AI for social good, human-AI alignment, AI governance, ethical AI.', 'Xia, Learning and Decision-Making from Rank Data, Morgan & Claypool, 2019. Barocas, Hardt and Narayanan, Fairness and Machine Learning: Limitations and Opportunities, MIT Press, 2023. Hendrycks, Introduction to AI Safety, Ethics, and Society, Taylor & Francis (forthcoming). Kleinberg et al, Human Decisions and Machine Predictions, Quarterly Journal of Economics, 2018. Plecko and Bareinboim, Causal Fairness Analysis, Foundations and Trends in ML, 2024. Ji et al, AI Alignment: A Comprehensive Survey, arXiv 2024.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS6104', 'Quantitative Verification', 'CSE', 'N/A', 'N/A', 'Prof. S. Akshay', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Modeling, specification and analysis of hardware, software and intelligent systems with a focus on quantitative aspects (time, probability, cost). Module 1: Markov chains and Markov decision processes, verification tools PRISM/STORM. Module 2: quantitative automata models (timed automata, hybrid automata, weighted automata), tools UPPAAL and Tchecker. Module 3: quantitative logics, richer specifications, model checking algorithms. Module 4: applications to intelligent systems (quantitative modeling of decision tree ensembles and neural networks; robustness, fairness, sensitivity, explainability).', 'Baier and Katoen, Principles of Model Checking, MIT Press, 2008. Alur and Dill, A Theory of Timed Automata, Theor. Comput. Sci. 126(2), 1994. Henzinger, Kopke, Puri and Varaiya, What`s Decidable about Hybrid Automata?, J. Comput. Syst. Sci. 57(1), 1998. Srivathsan, Reachability in Timed Automata, ACM SIGLOG News 9(3), 2022. Kwiatkowska, Norman and Parker, PRISM 4.0, Proc. CAV 2011. Korthikanti et al, Reasoning about MDPs as Transformers of Probability Distributions, QEST 2010. Albarghouthi, Introduction to Neural Network Verification, Found. Trends Program. Lang. 7(1-2), 2021.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS614', 'Advanced Compilers', 'CSE', 'N/A', 'N/A', 'Prof. Manas Thakur', 'Spring', '6', 'Exposure to a UG course on compilers', 'N/A', 'N/A', 'Introduction to code optimisation. Classical theory of data flow analysis, bi-directional data flows, unified and generalised algorithms for data flow analysis. Program representation for optimisation (SSA form etc). Efficient code generation for expressions, code generator generators (CGGs), code generation for pipelined machines. Register allocation techniques. Concurrentisation and vectorisation of programs.', 'Muchnick, Advanced Compiler Design and Implementation, Harcourt Asia, 2000. Srikant and Shankar (eds), The Compiler Design Handbook: Optimizations and Machine Code Generation, CRC Press, 2002. Nielson, Nielson and Hankin, Principles of Program Analysis, Springer Verlag, 1999. Morgan, Building an Optimizing Compiler, Digital Press, 1998. Allen and Kennedy, Optimizing Compilers for Modern Architectures, Morgan Kaufmann, 2002.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS681', 'Performance Analysis of Computer Systems and Networks', 'CSE', 'http://www.cse.iitb.ac.in/panda/courses/cs681/', 'N/A', 'Prof. Varsha Apte', 'Spring', '6', 'N/A', 'N/A', 'N/A', 'Introduction to performance measures and measurement, analytical modeling for performance, basic probability for performance evaluation, Markov chains, Markovian and non-Markovian queues, queueing networks, design/implementation/analysis of discrete event simulation models (confidence intervals). Applications to operating systems (paging, scheduling, multi-threading) and networks (web servers, TCP/IP models, wireless LAN, power management, virtualization).', 'Harchol-Balter, Performance Modeling and Design of Computer Systems: Queueing Theory in Action, Cambridge University Press, 2013. Trivedi, Probability and Statistics with Reliability, Queueing and Computer Science Applications, 2nd ed, Wiley, 2002. Akimaru and Kawashima, Teletraffic: Theory and Applications, Springer-Verlag, 1993. Kleinrock, Queueing Systems Vol I & II, Wiley, 1975. Law, Simulation Modeling and Analysis, Tata McGraw-Hill, 2007.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS713', 'Selected Topics in Automata and Logics', 'CSE', 'N/A', 'N/A', 'Prof. Bharat Adsul', 'Spring', '6', 'N/A', 'Full Semester', 'Theory', 'Introduction to automata on infinite words and infinite trees and connections to logics, fundamental to formal specification and verification of reactive systems, with possible coverage of basic finite model theory. Topics: automata on finite words (equivalence of MSO and automata); automata on infinite words (acceptance conditions, closure properties, determinization and complementation, equivalence to MSO, decidability); automata on infinite trees (acceptance conditions, closure properties, complementation via parity games, equivalence to MSO, decidability); parity games and determinacy; Ehrenfeucht-Fraisse games in logics and applications.', 'Thomas, Automata on Infinite Objects, Handbook of Theoretical Computer Science (vol B), Elsevier. Thomas, Languages, Automata, and Logic, Handbook of Formal Languages vol 3, Springer-Verlag. Perrin and Pin, Infinite Words, Elsevier. Gradel, Thomas and Wilke, Automata, Logics, and Infinite Games, LNCS, Springer-Verlag. Libkin, Elements of Finite Model Theory, Springer-Verlag.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS728', 'Organization of Web information', 'CSE', 'https://docs.google.com/document/d/1koNsAjmGZHAPxwr7qWyFnF94A1qetX-0ecubS0ugC5M/edit', 'N/A', 'Prof. Soumen Chakrabarti', 'Spring', '6', 'Foundations of Machine Learning and Web Search and Mining', 'N/A', 'N/A', 'Officially "Organizing Web Information," unofficially "Machine Learning for Natural Language and Knowledge Graphs" -- a continuation of CS635 ("Indexing and Retrieval of Text and Graphs"). No hard prerequisites; open to eligible students of all departments. Covers topics spanning attention mechanisms and positional encodings, efficient/long-context transformers, LLM safety and alignment limitations, memorization and knowledge editing in LLMs, retrieval-augmented generation, controllable text generation, hallucination in LLMs, tool use, and parameter-efficient fine-tuning (LoRA and variants).', 'A curated set of research papers on attention mechanisms, efficient transformers, LLM safety and alignment, knowledge editing, retrieval-augmented generation, hallucination, tool-use, and LoRA-based fine-tuning -- see course page for the full reading list.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS736', 'Medical Image Computing', 'CSE', 'https://www.cse.iitb.ac.in/~suyash/medical_image_computing.html', 'N/A', 'Prof. Suyash P. Awate', 'Spring', '6', 'Linear algebra, probability and statistics, data structures and algorithms, computing', 'N/A', 'Theory + Lab', 'Mathematical theory, algorithms, and computational aspects within advanced data science, image analysis, and machine learning topics applied to medical image computing. Includes hands-on computing experiments (Python/Matlab) on real-world medical image data. Topics: medical imaging modalities (X-ray, CT, MRI, diffusion MRI, functional MRI, PET, microscopy, ultrasound, 2D/3D/dynamic imaging); data visualization; image models (statistical, geometric, Markov random fields, texture, learned models); image reconstruction; image restoration; image segmentation and classification; statistical shape analysis; image registration; kernel methods in medical imaging; deep learning for medical image analysis.', 'Introduction to Mathematical Statistics (Hogg, McKean, Craig); Introduction to Probability and Statistics for Engineers and Scientists (Ross); Introduction to Linear Algebra (Strang); Applied Numerical Linear Algebra (Demmel); Practical Methods of Optimization (Fletcher); Digital Image Processing: An Algorithmic Introduction (Burger, Burge); Digital Image Processing (Gonzalez, Woods); Fundamentals of Digital Image Processing (Jain); Pattern Recognition and Machine Learning (Bishop); Markov Random Field Modeling in Image Analysis (Li); Deep Learning (Goodfellow, Bengio, Courville); Deep Learning Foundations and Concepts (C. Bishop, H. Bishop); Mathematics of Medical Imaging (Epstein); Medical Image Reconstruction (Zeng); Statistical Models of Shape (Davies, Twining, Taylor); Medical Image Registration (Hajnal, Hill, Hawkes); Visual Computing for Medicine (Preim, Botha); Medical Image Analysis (Frangi, Prince, Sonka); Handbook of Biomedical Imaging (Paragios, Duncan, Ayache); Deep Learning for Medical Image Analysis (Zhou, Greenspan, Shen)', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS748', 'Advances in Intelligent and Learning Agents', 'CSE', 'N/A', 'N/A', 'Prof. Shivaram Kalyanakrishnan', 'Spring', '6', 'N/A', 'N/A', 'N/A', 'Advanced topics and research projects building on "Foundations of Intelligent and Learning Agents." Topics may include contextual bandits, partially observable Markov decision problems, function approximation for reinforcement learning, sample complexity of reinforcement learning, Monte Carlo tree search, and evolutionary algorithms.', 'Primarily research papers from the last two decades, plus advanced topics from: Russell and Norvig, Artificial Intelligence: A Modern Approach, 3rd ed, Prentice-Hall, 2009. Sutton and Barto, Reinforcement Learning: An Introduction, MIT Press, 1998. Bertsekas, Dynamic Programming and Optimal Control Vol II, 4th ed, Athena Scientific. Bubeck and Cesa-Bianchi, Regret Analysis of Stochastic and Nonstochastic Multi-armed Bandit Problems, Foundations and Trends in ML, Vol 5, No 1.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS752', 'System Dynamics: Modeling & Simulation for Development', 'CSE', 'N/A', 'N/A', 'Prof. Om P. Damani', 'Spring', '6', 'N/A', 'N/A', 'N/A', 'Systems principles as the structure of knowledge: open and feedback systems, linear chain causality vs feedback systems. Feedback systems thinking / causal loop diagrams: causality, causal chains, link/loop polarities, positive/negative feedback loops, 1st/2nd order loops. Stock and flow: stock concept, rate of change, conservation of stock, system boundary. Computer simulation using Vensim; discrete time simulations; acyclic models. Fundamental modes of dynamic behavior: exponential growth, goal seeking, S-shaped growth. Model testing, calibration and behavior analysis. Multiple case studies (vary by offering). Optional advanced topics: parameter estimation via maximum likelihood and bootstrapping, Kalman filtering and state resetting for noisy data, stochastic optimization, decision analysis and simulation, optimal control for complex systems.', 'Rahmandad, Oliva and Osgood (eds), Analytical Methods for Dynamic Modelers, MIT Press, 2015. Morecroft, Strategic Modelling and Business Dynamics, 2nd ed: A Feedback Systems Approach, Wiley India, 2015.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS754', 'Advanced Image Processing', 'CSE', 'https://www.cse.iitb.ac.in/~ajitvr/CS754_Spring2025/', 'N/A', 'Prof. Ajit Rajwade', 'Spring', '6', 'CS 663 (Fundamentals of Digital Image Processing) or EE 610 (Image Processing) or CS 725 or CS 726 or Instructor Consent', 'Full Semester', 'Theory', 'Studies interesting mathematical properties of natural images -- local self-similarity across spatial regions, and sparsity of coefficients under transforms like wavelet or DCT -- and how these properties enable efficient, accurate algorithms for denoising, deblurring, image separation, compression, and forensics. Covers compressed sensing (faster image acquisition), inverse problems, and applications in tomographic reconstruction, reflection removal, image-based forensics, compressive reconstruction (video, MRI, hyperspectral imaging), low-rank matrix completion/recovery, phase retrieval, and robust/compressive PCA. Combines theory (including proofs), algorithms, and applications; relevant to machine learning, statistics, and signal processing as well as image processing.', 'Hyvarinen, Hurri and Hoyer, Natural Image Statistics, Springer Verlag, 2009 (freely available online). Foucart and Rauhut, A Mathematical Introduction to Compressive Sensing, Birkhauser, 2013. Hastie, Tibshirani and Wainwright, Statistical Learning with Sparsity: The Lasso and Generalizations, CRC Press (freely available online). Various research papers circulated during the course.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS758', 'Advanced Tools from Modern cryptography', 'CSE', 'https://www.cse.iitb.ac.in/~ckamath/courses/2026s/CS758.html', 'N/A', 'Prof. Manoj Prabhakaran', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Lattices have become a key source of hardness assumptions for post-quantum cryptography. This iteration looks at advanced cryptographic primitives -- identity-based encryption, fully-homomorphic encryption, and zero-knowledge proofs -- through the lens of lattices.', 'No textbook; relies on lecture notes and papers from the course reference list. Related courses: Peikert, Lattices in Cryptography (github.com/cpeikert/LatticesInCryptography). Vaikuntanathan, Advanced Topics in Cryptography: Lattices (6.876J), MIT.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS761', 'Derandomization and Pseudorandomness', 'CSE', 'N/A', 'N/A', 'Prof. Sruthi Sekar', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Randomized complexity classes (BPP, RP, RL) and motivation for derandomization; BPP subset of Exp; pairwise independence and error-reduction for BPP; polynomial identity testing (PIT) and applications; Miller-Rabin primality test and AKS derandomization; expander graphs, random walks, expander Chernoff bound; randomized and deterministic logspace algorithms for s-t connectivity; pseudorandom generators; hardness vs randomness; depth-2 PIT; small-bias spaces and almost k-wise independence; PRGs for RL (Nisan, INW); PIT for ROABPs and rank-1-determinant.', 'Arora and Barak, Computational Complexity: A Modern Approach, Cambridge University Press, 2009. Vadhan, Pseudorandomness, Now Publishers. Motwani and Raghavan, Randomized Algorithms, ACM, 1996. Agrawal, Kayal and Saxena, PRIMES is in P, Annals of Mathematics, 2004.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS763', 'Computer Vision', 'CSE', 'https://www.cse.iitb.ac.in/~sharat/current/cs763/', 'N/A', 'Prof. Sharat Chandran', 'Spring', '6', 'Either EE610/CS 663 (Fundamentals of Digital Image Processing) or CS 475/675 (Computer Graphics) or CS 740 (Mathematical Methods for Visual Computing).', 'N/A', 'N/A', 'Subset from: camera geometry, multi-view geometry and stereo vision; image registration (feature-point based registration, optical flow, robust registration); knowledge representation and inference; object detection; shape from shading and photometric stereo; structure from motion; computational photography and super-resolution.', 'Forsyth and Ponce, Computer Vision: A Modern Approach, Pearson, 2005. Trucco and Verri, Introductory Techniques for 3D Computer Vision, Prentice Hall, 1998. Bradski, Learning OpenCV: Computer Vision with the OpenCV Library, O`Reilly Media, 2008. Gonzalez and Woods, Digital Image Processing, 3rd ed, Pearson, 2008. Hartley and Zisserman, Multiple View Geometry, Cambridge Press, 2004. Plus deep learning papers.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS766', 'Analysis of Concurrent Programs', 'CSE', 'https://www.cse.iitb.ac.in/~akg/courses/2022-concurrency/', 'N/A', 'Prof. Krishna S', 'Spring', '6', 'CS 310 or CS 228', 'N/A', 'N/A', 'Module 1 (Practice of concurrency): mutual exclusion protocols (Bakery, Szymanski, Dijkstra, Dekker, Burns) with correctness proofs; concurrency in C++/Java/Android; concurrent objects and linearizability (sets, stacks, queues). Module 2 (Principles of verification): proof systems for concurrent programs (rely-guarantee, Owicki-Gries); automating proof systems via abstraction/model checking/refinement; proving linearizability of concurrent objects. Module 3 (Weak memory models): sequential consistency, total store order, release-acquire; verification of weak memory models (reachability problem in TSO/RA, decidability and complexity); dynamic partial order reduction algorithms, including the Tracer tool for RA.', 'Shavit, The Art of Multiprocessor Programming. Atig, Bouajjani, Burckhardt and Musuvathi, On the Verification Problem for Weak Memory Models, POPL 2010. Lahav, Giannarakis and Vafeiadis, Taming Release-Acquire Consistency, POPL 2016. Abdulla, Aronis, Jonsson and Sagonas, Source Sets: A Foundation for Optimal Dynamic Partial Order Reduction, J. ACM 64(4), 2017. Abdulla, Atig, Jonsson and Ngo, Optimal Stateless Model Checking under the Release-Acquire Semantics, OOPSLA 2018.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS773', 'Computer Architecture for Performance and Security', 'CSE', 'N/A', 'N/A', 'Prof. Biswabandan Panda', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Performance module: microarchitectural bottleneck analysis (desktop, mobile, servers); front-end/back-end optimizations (caching, prefetching, TLBs, MMU caches); memory hierarchy for multi/many-core systems (cache coherence, memory consistency); emerging memory systems (eDRAM, HBMs, NVMs like Intel Optane). Security module: transient execution attacks (Spectre, Meltdown); timing and conflict-based side channels through caches/TLBs/prefetchers/BTBs/branch predictors/DRAM controllers, attacks and mitigations; microarchitecture of Trusted Execution Environments (Intel SGX, ARM TrustZone, Keystone); physical attacks (row-hammer, data remanence, cold boot); reverse-engineering microarchitectural units and DNN models via microarchitecture; performance/security tradeoffs.', 'Hennessy and Patterson, Computer Architecture, Morgan Kaufmann, 2017. Arpaci-Dusseau and Arpaci-Dusseau, Operating Systems: Three Easy Pieces, 2015. Synthesis Lectures on caching, prefetching, memory systems, virtualization, and security, Morgan & Claypool, 2010-2021. Research papers from ISCA, MICRO, HPCA, PACT, ASPLOS, USENIX Security, S&P, NDSS.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS778', 'R & D Project II (MSR)', 'CSE', 'N/A', 'N/A', 'Varies by student', 'Spring', '8', 'N/A', 'N/A', 'N/A', 'Individual research and development project supervised by a faculty advisor, part of the MSR program.', 'N/A', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS781', 'Formal Methods in Machine Learning', 'CSE', 'N/A', 'N/A', 'Prof. Supratik Chakraborty', 'Spring', '6', 'CS228, CS213, CS337 or equivalent, or familiarity with propositional/first-order logic, data structures and algorithms, and basic machine learning theory', 'N/A', 'Theory', 'Relevant logic and ML basics (Hoare triples, feed-forward DNNs, reinforcement learning, PAC learning). Feed-forward deep neural networks through the lens of formal methods: modeling via systems of constraints and abstraction/refinement; property specification (safety, robustness, fairness); constraint-solving techniques (case study: ReLUplex/ACAS-Xu); abstraction-refinement techniques (case study: DeepPoly/MNIST); robustness analysis via constraint solving and model counting; explainable interpretations with guarantees. Reinforcement learning through the lens of formal methods: shield synthesis for safe RL using MDPs; safe RL via justified speculative control; safe RL via decision tree policy extraction.', 'Albarghouthi, Introduction to Neural Network Verification, online e-book, 2020, plus roughly one paper/article per week covering topics including verified AI, ReLUplex, abstraction domains for certifying neural networks, verifying binarized DNNs, explanation methods, shielding for safe RL, and policy extraction for verifiable RL.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS784', 'Image Synthesis', 'CSE', 'https://www.cse.iitb.ac.in/~paragc/course/2024-01-cs784/', 'N/A', 'Prof. Parag Kumar Chaudhuri', 'Spring', '6', 'Prior background in Computer Graphics, Image Processing, or Computer Vision is highly desirable.', 'N/A', 'Theory + Project', 'Covers the process of image formation/synthesis on a computer, starting from classical Computer Graphics rendering methods through modern neural rendering. Not a deep learning course -- a visual computing course, hands-on with theory, programming assignments, and DCC platforms like Blender. Topics: global illumination and rendering, radiometry/photometry, ray tracing, surface reflectance and BRDFs, Monte Carlo path tracing, photon mapping, volume rendering, image-based rendering, view morphing and novel view synthesis, plenoptic function/lightfields; neural and differentiable rendering (neural scene representation, NeRFs, differentiable/inverse rendering); image synthesis from text/audio/images (generative models); image synthesis for VR/AR (spherical panoramas, neural antialiasing, foveated rendering, VR discomfort causes); real vs synthetic image statistics and fake image detection.', 'Pharr, Jakob and Humphreys, Physically Based Rendering, 4th ed, 2023, MIT Press. CVPR 2020 and SIGGRAPH 2021 courses on Neural Rendering. Glassner, Principles of Digital Image Synthesis, Vol 1 & 2, Morgan Kaufmann, 1995. Szeliski, Computer Vision: Algorithms and Applications, 2nd ed, Springer, 2023. Relevant research papers from CVPR, SIGGRAPH, Eurographics, ICCV, NeurIPS.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS786', 'Randomized Algorithms', 'CSE', 'N/A', 'N/A', 'Prof. Akash Kumar', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Polynomial identity testing; Karger`s algorithm for minimum cut; linearity of expectation and applications; Markov and Chebyshev bounds and applications; Chernoff bound with high-probability bounds for quicksort and median estimation; importance sampling (Karp-Luby); estimating average degree of a graph via random sampling; understanding the upper tail and proof of the Chernoff bound; the probabilistic method; dimension reduction and the Johnson-Lindenstrauss lemma; martingales and the optional stopping theorem; Yao`s lemma and lower bounds for randomized algorithms.', 'Motwani and Raghavan, Randomized Algorithms, Cambridge University Press, 1995. Mitzenmacher and Upfal, Probability and Computing: Randomized Algorithms and Probabilistic Analysis, 2nd ed, Cambridge University Press, 2017. Alon and Spencer, The Probabilistic Method, 4th ed, Wiley, 2016. Dubhashi and Panconesi, Concentration of Measure for the Analysis of Randomized Algorithms, Cambridge University Press. Moore and Mertens, The Nature of Computation, Oxford University Press, 2011. Venkatesh, Theory of Probability: Explorations and Applications, Cambridge University Press, 2011.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS789', 'Introduction to Probabilistic Proof Systems', 'CSE', 'https://www.cse.iitb.ac.in/~ckamath/courses/2027s/CS789.html', 'N/A', 'Prof. Chethan Kamath', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Explores relaxing the traditional notion of theorem/proof to "probabilistic" proofs where soundness holds with high enough probability. Covers interactive proofs (efficient verification), probabilistically-checkable proofs (checking only a small part of a proof), zero-knowledge proofs (verifying knowledge of a solution without revealing it), and SNARKs (verifying delegated computation). Studies theoretical consequences to complexity theory and cryptography, and practical applications from blockchains to cloud computing.', 'Thaler, Proofs, Arguments, and Zero-Knowledge, lecture notes/monograph. Goldreich, Foundations of Cryptography, Vols I-II, Cambridge University Press, 2001/2004. Arora and Barak, Computational Complexity: A Modern Approach, Cambridge University Press, 2009. Chiesa and Yogev, Building Cryptographic Proofs from Hash Functions, monograph. Chiesa, Foundations of Probabilistic Proofs (course). Thaler, Probabilistic Proof Systems (course).', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS790', 'Privacy Enhancing Technologies', 'CSE', 'N/A', 'N/A', 'Prof. Devashish Gosain', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Explores research on identifying and countering privacy/network threats: traffic filtering (mechanisms, content-blocking triggers, IP tables, raw sockets); measurement techniques to detect firewalls (SSL/TLS inspection, DNS/HTTP/TLS leaks, traceroutes); the Great Firewall of China as a case study; identifying loopholes in firewalls (middlebox characterization, latency measurement). Privacy topics: definitions across network layers; web tracking (cookies, browser fingerprinting); anti-tracking techniques; privacy law (GDPR, CCPA, DPDPA); anonymity (definitions, Tor, mixnets). Combination of lectures, paper reading, and hands-on programming assignments/projects.', 'Research papers from NDSS, IMC, USENIX Security, CCS, PETS. Kurose and Ross, Computer Networks: A Top-Down Approach, 6th ed, Pearson. Stallings and Brown, Computer Security: Principles and Practice, 3rd ed, Pearson. Stallings, Cryptography and Network Security: Principles and Practice, 8th ed, Pearson, 2022. Viega, Messier and Chandra, Network Security with OpenSSL, O`Reilly Media, 2002. Forouzan, Data Communications and Networking, 5th ed, McGraw-Hill, 2013.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS791', 'Probabilistic Foundations of AI', 'CSE', 'https://www.cse.iitb.ac.in/~sunita/cs791/', 'N/A', 'Prof. Sunita Sarawagi', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Advanced statistics, machine learning and algorithmic foundations of modern generative AI, themed around modeling, training, and generation of multiple inter-dependent variables. Topics: probabilistic graphical models (Bayesian networks, message passing inference), energy-based models, sampling methods (importance sampling, MCMC/Langevin MC); deep latent generative models (VAEs, normalizing flows, GANs, diffusion models for continuous/discrete data, constrained generation); efficient and constrained inference for LLMs; adaptation of pre-trained models (fine-tuning, in-context learning, model stitching, continual learning). Techniques linked to applications in NLP, vision, databases, and sciences.', 'Koller and Friedman, Probabilistic Graphical Models: Principles and Techniques, MIT Press, 2009. Chan, Tutorial on Diffusion Models for Imaging and Vision, arXiv:2403.18103, 2024. Welleck et al, From Decoding to Meta-Generation, arXiv:2406.16838, 2024. Kingma and Welling, Auto-Encoding Variational Bayes, arXiv:1312.6114, 2013. Dong et al, A Survey on In-context Learning, EMNLP 2024.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');

INSERT INTO courses (course_code, title, department, home_page, autumn_instructor, spring_instructor, semester, credits, prerequisites, duration, course_type, syllabus_text, references_text, source_url, last_updated)
VALUES ('CS794', 'Systems for Machine Learning', 'CSE', 'N/A', 'N/A', 'Prof. Mythili Vutukuru', 'Spring', '6', 'N/A', 'N/A', 'Theory', 'Review of deep learning model basics and architectures including transformers, with emphasis on workload characteristics (matrix operations, attention computation, FLOPS/memory requirements). Modern GPU architectures and performance concepts (arithmetic intensity, compute vs memory bound workloads, hardware-aware optimizations like tiling). Programming frameworks and compilers for AI/ML systems (TensorFlow, PyTorch). Hardware-aware and software-defined optimizations: KV caching, efficient attention algorithms (FlashAttention), model compression (pruning, quantization, knowledge distillation). Training and inference at scale: parallel/distributed training techniques, case studies (Llama 3, DeepSeek), high-performance LLM inference serving (KV cache memory optimization, batching, parallelism, offload, scheduling). Lab exercises in CUDA programming and building ML pipelines in PyTorch; may include a project component.', 'Rodriguez, Deep Learning Systems: Algorithms, Compilers, and Processors for Large-Scale Production, Springer, 2022. Janapa Reddi, Machine Learning Systems: Principles and Practices of Engineering Artificially Intelligent Systems, 2025 (mlsysbook.ai). Burkov, The Hundred-Page Language Models Book, 2025, and The Hundred-Page Machine Learning Book, 2019. Alammar and Grootendorst, Hands-on Large Language Models, O`Reilly, 2024. Aamodt, Fung and Rogers, General-Purpose Graphics Processor Architectures, Springer, 2022.', 'https://www.cse.iitb.ac.in/academics/courses', '2026-08-04');
